import { Check, Copy } from "lucide-react";
import { useState } from "react";

import { Button } from "@/components/ui/button";

/**
 * An order's / booking's payment reference (128-bit, 32 hex characters, generated by the backend):
 * what the payment is made under, and what payment events come back with. Shown in full, with a copy button.
 */
export function PaymentReference({ reference }: { reference: string }) {
  const [status, setStatus] = useState<"idle" | "copied" | "failed">("idle");

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(reference);
      setStatus("copied");
    } catch {
      setStatus("failed"); // e.g. no clipboard access: the text can still be selected by hand
    }
    setTimeout(() => setStatus("idle"), 2000);
  };

  return (
    <div className="grid min-w-0 gap-0.5">
      <span className="text-muted-foreground text-xs">Payment reference</span>
      <div className="flex min-w-0 items-center gap-1">
        <code className="truncate font-mono text-sm" title={reference}>
          {reference}
        </code>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="size-7 shrink-0"
          onClick={copy}
          aria-label="Copy payment reference"
        >
          {status === "copied" ? <Check /> : <Copy />}
        </Button>
      </div>
      {status === "failed" && (
        <span role="alert" className="text-destructive text-xs">
          Couldn't copy: select the text and copy it yourself.
        </span>
      )}
    </div>
  );
}
